mapper.select:
SELECT id, title, content, knowledge_scope AS knowledgeScope, source_type AS sourceType, venue_id AS venueId, venue_name AS venueName, court_id AS courtId, court_name AS courtName, court_type AS courtType, notice_id AS noticeId, topic, tags, priority, enabled, indexed_status AS indexedStatus, create_time AS createTime, update_time AS updateTime FROM knowledge_document WHERE 1 = 1
AND title LIKE CONCAT('%', #{title}, '%')
AND knowledge_scope = #{knowledgeScope}
AND source_type = #{sourceType}
AND venue_id = #{venueId}
AND court_id = #{courtId}
AND enabled = #{enabled}
AND indexed_status = #{indexedStatus}
ORDER BY priority DESC, id DESC

mapper.update:
UPDATE knowledge_document
SET enabled = #{enabled},
    indexed_status = 0,
    update_time = #{date}
WHERE id = #{id}

update knowledge_document
set is_deleted = 1
WHERE id = #{id}

UPDATE knowledge_document
SET indexed_status = 1,
    update_time = #{date}
WHERE id = #{id}
